[[gnu::always_inline]] LIBC_INLINE long syscall_impl(long number, long arg1,
                                                     long arg2, long arg3,
                                                     long arg4, long arg5) {
  REGISTER_DECL_5;
  SYSCALL_INSTR(REGISTER_CONSTRAINT_5);
  return x0;
}

[[gnu::always_inline]] LIBC_INLINE long syscall_impl(long number, long arg1,
                                                     long arg2, long arg3,
                                                     long arg4, long arg5,
                                                     long arg6) {
  REGISTER_DECL_6;
  SYSCALL_INSTR(REGISTER_CONSTRAINT_6);
  return x0;
}

